class L{String s(boolean p,String[]I){long A=0;for(var l:I){var t=l.split("\\s+");var q=t[1].split(",");int n=q.length*(p?1:5),m=0;var g=new int[n];for(int i=n;i-->0;)m=Math.max(m,g[i]=new Integer(q[i%q.length]));var s=t[0];if(!p)for(int i=4;i-->0;)s+="?"+t[0];long[][]d=new long[n+1][m+1],e;d[0][0]=1;for(char c:(s+".").toCharArray()){e=new long[n+1][m+1];for(int j=0;j<=n;j++)for(int r=0;r<=m;r++){long v=d[j][r];if(c!=35)if(r<1)e[j][0]+=v;else if(j<n&&r==g[j])e[j+1][0]+=v;if(c!=46&j<n&&r<g[j])e[j][r+1]+=v;}d=e;}A+=d[n][0];}return""+A;}}
